create extension if not exists pg_trgm;
create type public.user_role as enum ('admin','viewer');
create type public.verification_status as enum ('unverified','requires_review','verified');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role public.user_role not null default 'viewer',created_at timestamptz not null default now());
create table public.uploaded_pdfs(id uuid primary key default gen_random_uuid(),filename text not null,part_number int not null check(part_number in(227,228,229,230)),total_pdf_pages int not null check(total_pdf_pages>0),processed_pages int not null default 0,failed_pages int not null default 0,records_count int not null default 0,processing_status text not null,storage_path text not null unique,checksum text not null unique,uploaded_by uuid not null default auth.uid() references auth.users(id),uploaded_at timestamptz not null default now());
create table public.voter_records(id uuid primary key default gen_random_uuid(),pdf_id uuid not null references public.uploaded_pdfs(id) on delete cascade,part_number int not null check(part_number in(227,228,229,230)),serial_number text,original_name text,normalized_name text,relation_type text not null check(relation_type in('Father','Mother','Husband','Guardian','Other','Unknown')),original_relation_name text,normalized_relation_name text,original_house_number text,normalized_house_number text,age int check(age between 18 and 125),gender text,epic_number text,pdf_page_number int not null check(pdf_page_number>0),printed_page_number int,original_text text not null,original_language text,ocr_confidence real check(ocr_confidence between 0 and 100),bounding_box jsonb,verification_status public.verification_status not null default 'unverified',corrected_value jsonb,corrected_by uuid references auth.users(id),corrected_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(pdf_id,part_number,serial_number,pdf_page_number));
create table public.page_processing(id bigint generated always as identity primary key,pdf_id uuid not null references public.uploaded_pdfs(id) on delete cascade,pdf_page_number int not null,printed_page_number int,status text not null,created_at timestamptz not null default now(),unique(pdf_id,pdf_page_number));
create index voter_name_trgm on public.voter_records using gin(normalized_name gin_trgm_ops);create index voter_relation_trgm on public.voter_records using gin(normalized_relation_name gin_trgm_ops);create index voter_search_exact on public.voter_records(part_number,normalized_house_number,age,gender,epic_number,serial_number);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
alter table public.profiles enable row level security;alter table public.uploaded_pdfs enable row level security;alter table public.voter_records enable row level security;alter table public.page_processing enable row level security;
create policy "own profile" on public.profiles for select to authenticated using(id=auth.uid());
create policy "read documents" on public.uploaded_pdfs for select to authenticated using(true);create policy "admin documents" on public.uploaded_pdfs for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read voters" on public.voter_records for select to authenticated using(true);create policy "admin voters" on public.voter_records for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "read pages" on public.page_processing for select to authenticated using(true);create policy "admin pages" on public.page_processing for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('voter-pdfs','voter-pdfs',false,104857600,array['application/pdf']) on conflict(id) do nothing;
create policy "authenticated read pdf" on storage.objects for select to authenticated using(bucket_id='voter-pdfs');create policy "admin upload pdf" on storage.objects for insert to authenticated with check(bucket_id='voter-pdfs' and public.is_admin());
